import{defineJsonSchema}from"#tools/schema.js";import{frameworkTool}from"#tools/provided/framework-tool.js";import{defineWorkflowTool}from"#tools/workflow-definition.js";import{agentWithModelServeWorkflow}from"#runtime/subagents/workflow.js";import{agent}from"#tools/framework/agent.js";const inputSchema=defineJsonSchema({type:`object`,properties:{message:{type:`string`,description:`The message to send to the agent, with everything it needs to do the work.`},model:{type:`string`,minLength:1,description:`AI Gateway model id for a new child session. When continuing a task, use its original model.`}},required:[`message`,`model`],additionalProperties:!1}),agentWithModel=frameworkTool(defineWorkflowTool({availableInSubagents:!1,description:`Delegate a focused subtask to a copy of yourself using the selected AI Gateway model. Each call starts a task, so start independent tasks before waiting for them. A continuation keeps its task's original model. In message, state the goal, what to return, and whether it may change files.`,inputSchema,serve:agentWithModelServeWorkflow}));export{agent,agent as default,agentWithModel};